const adj=i=>[i%9?i-1:-1,i%9<8?i+1:-1,i>=9?i-9:-1,i<72?i+9:-1].filter(j=>j>=0);
const idx=p=>(9-Number(p[1]))*9+"ABCDEFGHJ".indexOf(p[0]);
const name=i=>"ABCDEFGHJ"[i%9]+(9-Math.floor(i/9));
const b=Array(81).fill("."),caps={X:0,O:0},states=[{board:[...b],caps:{...caps},ko:null}],events=[];
let ko=null;const koEvents=[];
function chain(i){const todo=[i],s=new Set([i]),libs=new Set();while(todo.length){const k=todo.pop();for(const j of adj(k)){if(b[j]===".")libs.add(j);else if(b[j]===b[i]&&!s.has(j)){s.add(j);todo.push(j)}}}return {s:[...s],libs:[...libs]}}
for(const m of log.moves){const c=m.color==="B"?"X":"O",enemy=c==="X"?"O":"X";if(m.n!==states.length||m.color!==(m.n%2?"B":"W"))throw Error("move order");if(m.move==="pass"){ko=null}else{const i=idx(m.move);if(b[i]!=="."||i===ko)throw Error("occupied/ko "+m.n);b[i]=c;const removed=[];for(const j of adj(i)){if(b[j]!==enemy)continue;const g=chain(j);if(!g.libs.length)for(const k of g.s){b[k]=".";removed.push(k)}}const own=chain(i);if(!own.libs.length)throw Error("suicide "+m.n);caps[c]+=removed.length;ko=removed.length===1&&own.s.length===1&&own.libs.length===1?removed[0]:null;if(removed.length)events.push({n:m.n,color:m.color,move:m.move,captured:removed.map(name).sort()})}if(ko!==null)koEvents.push({after:m.n,point:name(ko)});states.push({board:[...b],caps:{...caps},ko:ko===null?null:name(ko)});}
const checks=[];for(const raw of log.raw){const t=raw.response.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");const next=Number(t.match(/Move number: (\d+)/)?.[1]),s=states[next-1],view=inspect(raw.response);if(!s||JSON.stringify(s.board)!==JSON.stringify(view.board))throw Error("board "+raw.kind);const counts=t.match(/Captured by Black: (\d+); by White: (\d+)/);if(!counts||Number(counts[1])!==s.caps.X||Number(counts[2])!==s.caps.O)throw Error("capture "+raw.kind);const k=t.match(/Ko point: ([A-HJ][1-9]|none)/)?.[1];if(k!==(s.ko||"none"))throw Error("ko "+raw.kind);checks.push({kind:raw.kind,next,captures:s.caps,ko:s.ko,matched:true});}
